// JAH demo program — First-sixty drill
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
var __steps=["Park to shield the scene from traffic", "One-sentence radio report with command declaration", "Assign three jobs out loud", "Start the time-critical intervention clock"];
__steps.forEach(function(s,i){console.log("step "+(i+1)+": "+s);});
check("step count", __steps.length, 4);
function sixtyOK(jobs){ return jobs>=3?'command rhythm set':'assign three jobs'; }
check("three jobs assigned", sixtyOK(3), "command rhythm set");
check("one job", sixtyOK(1), "assign three jobs");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

